script:
# 🔹 Run only if relevant fields changed
if doc.has_value_changed("forward_to") or doc.has_value_changed("forward_reason"):

    # 🔹 Proceed only if doctor is selected
    if doc.forward_to:

        # 🔹 Build description
        description = f"Ticket {doc.name} assigned to you"

        if doc.forward_reason:
            description += f"\nReason: {doc.forward_reason}"

        # 🔹 Remove existing assignments
        assignments = frappe.get_all(
            "ToDo",
            filters={
                "reference_type": doc.doctype,
                "reference_name": doc.name,
                "status": ("!=", "Cancelled")
            },
            fields=["name"]
        )

        for d in assignments:
            frappe.delete_doc("ToDo", d.name, ignore_permissions=True)

        # 🔹 Create new assignment
        frappe.get_doc({
            "doctype": "ToDo",
            "owner": doc.forward_to,
            "assigned_by": frappe.session.user,
            "reference_type": doc.doctype,
            "reference_name": doc.name,
            "description": description,
            "status": "Open"
        }).insert(ignore_permissions=True)
